create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null, handle text unique not null, bio text default '', avatar_url text, verified boolean default false, followers_count int default 0, following_count int default 0, created_at timestamptz default now());
create table if not exists stores(id uuid primary key default gen_random_uuid(), owner_id uuid references profiles(id) on delete cascade, name text not null, slug text unique not null, description text default '', lat double precision, lng double precision, rating numeric(3,2) default 0, verification_status text default 'pending', created_at timestamptz default now());
create table if not exists products(id uuid primary key default gen_random_uuid(), store_id uuid references stores(id) on delete cascade, name text not null, description text default '', category text not null, price numeric(12,2) not null, currency text default 'GHS', stock int default 0, fulfillment text default 'local', estimated_arrival text, image_urls text[] default '{}', attributes jsonb default '{}', created_at timestamptz default now());
create table if not exists posts(id uuid primary key default gen_random_uuid(), author_id uuid references profiles(id) on delete cascade, body text not null, media_urls text[] default '{}', product_id uuid references products(id), visibility text default 'public', repost_of uuid references posts(id), created_at timestamptz default now());
create table if not exists follows(follower_id uuid references profiles(id) on delete cascade, following_id uuid references profiles(id) on delete cascade, created_at timestamptz default now(), primary key(follower_id,following_id));
create table if not exists conversations(id uuid primary key default gen_random_uuid(), kind text not null, title text, created_at timestamptz default now());
create table if not exists conversation_members(conversation_id uuid references conversations(id) on delete cascade, user_id uuid references profiles(id) on delete cascade, joined_at timestamptz default now(), primary key(conversation_id,user_id));
create table if not exists messages(id uuid primary key default gen_random_uuid(), conversation_id uuid references conversations(id) on delete cascade, sender_id uuid references profiles(id), body text, media jsonb default '{}', status text default 'sent', created_at timestamptz default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(), buyer_id uuid references profiles(id), store_id uuid references stores(id), product_id uuid references products(id), quantity int not null, subtotal numeric(12,2) not null, delivery_fee numeric(12,2), address jsonb not null, payment_reference text unique, payment_status text default 'pending', fulfillment_status text default 'awaiting_payment', created_at timestamptz default now());
create table if not exists bids(id uuid primary key default gen_random_uuid(), product_id uuid references products(id), bidder_id uuid references profiles(id), amount numeric(12,2) not null, created_at timestamptz default now());
create index if not exists products_category_idx on products(category); create index if not exists products_store_idx on products(store_id); create index if not exists posts_author_idx on posts(author_id); create index if not exists messages_conversation_idx on messages(conversation_id); create index if not exists orders_buyer_idx on orders(buyer_id);
